const CALCULATE_SCHEMA = {
  type: 'object',
  properties: {
    a: { type: 'number' },
    b: { type: 'number' },
    operation: { type: 'string', enum: OPERATIONS },
  },
  required: ['a', 'b', 'operation'],
  additionalProperties: false,
};

export async function listTools() {
  return [
    {
      name: 'calculate',
      description: 'Perform a basic arithmetic operation on two numbers.',
      inputSchema: CALCULATE_SCHEMA,
    },
  ];
}

export async function callTool(name, args) {
  if (name !== 'calculate') {
    throw new Error(`Unknown tool: ${name}`);
  }
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }

  const allowed = new Set(['a', 'b', 'operation']);
  const keys = Object.keys(args);
  for (const key of keys) {
    if (!allowed.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  const { a, b, operation } = args;

  if (!('a' in args)) throw new Error('Missing required field: a');
  if (!('b' in args)) throw new Error('Missing required field: b');
  if (!('operation' in args)) throw new Error('Missing required field: operation');

  if (typeof a !== 'number' || !Number.isFinite(a)) {
    throw new Error('Field "a" must be a finite number');
  }
  if (typeof b !== 'number' || !Number.isFinite(b)) {
    throw new Error('Field "b" must be a finite number');
  }
  if (typeof operation !== 'string' || !OPERATIONS.includes(operation)) {
    throw new Error(`Unsupported operation: ${operation}`);
  }

  let result;
  switch (operation) {
    case 'add':
      result = a + b;
      break;
    case 'subtract':
      result = a - b;
      break;
    case 'multiply':
      result = a * b;
      break;
    case 'divide':
      if (b === 0) {
        throw new Error('Division by zero');
      }
      result = a / b;
      break;
    default:
      throw new Error(`Unsupported operation: ${operation}`);
  }

  return {
    content: [{ type: 'text', text: String(result) }],
  };
}
